   "desc": "Нарукавный знак на полевую, повседневную и специальную форму одежды военнослужащих спасательных воинских формирований МЧС России, сотрудников ФПС ГПС и отдельных категорий работников МЧС России выполнен в виде полукруга (высота 40 мм, ширина 85 мм) в цвет флага Российской Федерации с окантовкой золотистого цвета.\nВ основании полукруга, на полосе в цвет ткани верха формы одежды в один ряд буквами золотистого цвета нанесена надпись: \"РОССИЯ\" (\"RUSSIA\")",
