   "kind": "Нарукавный",
   "status": "have",
   "desc": "Нарукавный знак на парадную, повседневную, полевую и специальную форму одежды военнослужащих спасательных воинских формирований МЧС России, сотрудников ФПС ГПС и отдельных категорий работников МЧС России выполнен в виде фигурного щита (высота 110 мм, ширина 85 мм) с окантовкой золотистого цвета.\nПоле щита - в цвет ткани верха формы одежды.\nВ центре щита изображена малая эмблема МЧС России, обрамленная снизу оливковыми ветвями золотистого цвета.\nВ верхней части щита в один ряд буквами золотистого цвета нанесена надпись: \"МЧС РОССИИ\"",
