   "desc": "Нарукавный знак на парадную, повседневную, полевую и специальную форму одежды военнослужащих спасательных воинских формирований МЧС России, сотрудников ФПС ГПС и отдельных категорий работников главных управлений МЧС России по субъектам Российской Федерации представляет собой фигурный щит (высота 110 мм, ширина 85 мм) с окантовкой золотистого цвета.\nПоле щита - в цвет ткани верха формы одежды.\nВ центре щита расположена эмблема Главного управления МЧС России по субъекту Российской Федерации, представляющая собой изображение двуглавого орла золотистого цвета с опущенными крыльями и увенчанного короной.\nОрел держит в лапах прикрывающий его грудь фигурный щит с окантовкой серебристого цвета.\nВ поле щита - основные элементы герба субъекта Российской Федерации, в котором располагается Главное управление МЧС России по субъекту Российской Федерации.\nЩит наложен на два диагонально перекрещенных шестопера серебристого цвета.\nНад эмблемой Главного управления МЧС России - преломленный Государственный флаг Российской Федерации.\nВ верхней части щита в один ряд буквами золотистого цвета нанесена надпись: \"МЧС РОССИИ\", в нижней части щита - изогнутая по форме щита в один ряд буквами золотистого цвета надпись с наименованием Главного управления МЧС России по субъекту Российской Федерации.",
