   "desc": "Нарукавный знак на парадную, повседневную, полевую и специальную форму одежды военнослужащих спасательных воинских формирований МЧС России и отдельных категорий работников федерального государственного казенного учреждения \"Ногинский спасательный центр Министерства Российской Федерации по делам гражданской обороны, чрезвычайным ситуациям и ликвидации последствий стихийных бедствий\" выполнен в виде фигурного щита (высота 110 мм, ширина 85 мм) с окантовкой золотистого цвета.\nПоле щита - в цвет ткани верха формы одежды.\nВ центре щита на фоне земного шара голубого цвета, переплетенного лентой с полосами белого, синего и красного цветов, изображена бегущая лошадь белого цвета.\nЗемной шар огибает лента оранжевого цвета. В верхней части щита в один ряд буквами синего цвета нанесена надпись: \"СПАСАТЕЛЬНЫЙ ЦЕНТР МЧС РОССИИ\", под эмблемой федерального государственного казенного учреждения \"Ногинский спасательный центр Министерства Российской Федерации по делам гражданской обороны, чрезвычайным ситуациям и ликвидации последствий стихийных бедствий\" в один ряд буквами синего цвета надпись - \"НОГИНСКИЙ\".\nВ нижней части щита, под лентой - малая эмблема МЧС России, обрамленная оливковыми ветвями золотистого цвета.",
